function fibonacci(n: number): number[] {
  const deret: number[] = [];
  let a = 0, b = 1;
  for (let i = 0; i < n; i++) {   // FOR: n sudah diketahui
    deret.push(a);
    [a, b] = [b, a + b];
  }
  return deret;
}

function banyakSukuDiBawah(batas: number): number {
  let a = 0, b = 1, banyak = 0;
  while (a < batas) {             // WHILE: berhenti saat melewati batas
    banyak++;
    [a, b] = [b, a + b];
  }
  return banyak;
}

